import { chromium } from "playwright";
import assert from "node:assert/strict";
import { mkdir } from "node:fs/promises";
const browser = await chromium.launch({ channel: "chrome", headless: true });
const page = await browser.newPage({ viewport: { width: 1440, height: 1100 } });
const errors = []; page.on("pageerror", error => errors.push(error.message));
await page.goto("http://127.0.0.1:8789");
await page.getByRole("heading", { name: "Who should know?" }).waitFor();
await mkdir("/tmp/tape-intel-review", { recursive: true });
await page.screenshot({ path: "/tmp/tape-intel-review/desktop.png", fullPage: true });
await page.getByText("View source", { exact: true }).first().click();
await page.getByText(/We want to work with inference teams/).first().waitFor();
await page.getByRole("button", { name: /Alex is looking for inference teams/ }).click();
await page.getByRole("heading", { name: "Maya Patel" }).waitFor();
await page.screenshot({ path: "/tmp/tape-intel-review/results.png", fullPage: true });
await page.getByRole("button", { name: "Maya Patel", exact: true }).click();
await page.getByRole("dialog").waitFor();
assert.equal(await page.getByRole("checkbox").count(), 1);
await page.getByRole("dialog").getByRole("button", { name: "Find matches" }).click();
await page.getByRole("heading", { name: /Alex is looking for inference teams/ }).waitFor();
await page.getByRole("button", { name: "New search", exact: true }).first().click();
await page.getByRole("textbox").fill("fail to read this link");
await page.getByRole("textbox").press("Enter");
await page.getByRole("alert").waitFor();
assert.match(await page.getByRole("textbox").inputValue(), /fail/);
await page.getByRole("button", { name: "New search", exact: true }).first().click();
await page.setViewportSize({ width: 390, height: 844 });
await page.screenshot({ path: "/tmp/tape-intel-review/mobile.png", fullPage: true });
assert.ok(await page.evaluate(() => document.documentElement.scrollWidth <= innerWidth));
await page.getByRole("tab", { name: "People", exact: true }).click();
await page.getByRole("button", { name: /Alex Chen/ }).first().click();
assert.equal(await page.getByRole("checkbox").count(), 2);
assert.equal(await page.getByRole("checkbox").nth(1).isChecked(), false);
await page.getByRole("checkbox").nth(1).check();
await page.getByRole("dialog").waitFor();
await page.keyboard.press("Escape");
await page.getByRole("dialog").waitFor({ state: "hidden" });
await page.getByRole("button", { name: "New search", exact: true }).first().click();
await page.getByRole("textbox").fill("newly indexed");
await page.getByRole("textbox").press("Enter");
await page.getByRole("button", { name: "Jordan Lee", exact: true }).click();
await page.getByRole("dialog").getByRole("button", { name: "Find matches" }).click();
await page.getByRole("button", { name: "A newly indexed opportunity for enterprise inference.", exact: true }).click();
await page.getByRole("heading", { name: "Jordan Lee" }).waitFor();
assert.equal(await page.getByText("Unavailable intel", { exact: true }).count(), 0);
await page.setViewportSize({ width: 1440, height: 1100 });
await page.evaluate(() => { const original = window.fetch; window.fetch = async (input, init) => init?.method === "DELETE" ? new Response(null, { status: 500 }) : original(input, init); });
await page.getByRole("button", { name: "Clear history", exact: true }).click();
await page.getByRole("alert").filter({ hasText: "Could not clear history" }).waitFor();
assert.equal(await page.getByRole("button", { name: "Try again", exact: true }).count(), 0);
await page.getByRole("heading", { name: "Jordan Lee" }).waitFor();
assert.deepEqual(errors, []);
await page.getByRole("button", { name: "New search", exact: true }).first().click();
await page.getByRole("textbox").fill("finish while away");
await page.getByRole("textbox").press("Enter");
await page.getByText("Matching and checking evidence · 1 of 2 steps").waitFor();
assert.equal(await page.getByRole("progressbar").getAttribute("value"), "1");
await browser.close();
// The fixture worker must finish while there is no browser available to poll it.
const deadline = Date.now() + 10000;
let saved;
do {
  saved = (await (await fetch("http://127.0.0.1:8789/api/intel/search")).json()).job;
  if (saved.status === "complete") break;
  await new Promise(resolve => setTimeout(resolve, 200));
} while (Date.now() < deadline);
assert.equal(saved.status, "complete");
assert.equal(saved.input.text, "finish while away");
const returned = await chromium.launch({ channel: "chrome", headless: true });
const reopened = await returned.newPage();
let submissions = 0;
reopened.on("request", req => { if (req.method() === "POST" && req.url().includes("/api/intel/search")) submissions++; });
await reopened.goto("http://127.0.0.1:8789");
await reopened.getByRole("heading", { name: "Jordan Lee" }).or(reopened.getByRole("heading", { name: "Maya Patel" })).waitFor();
assert.equal(await reopened.getByRole("textbox").inputValue(), "finish while away");
assert.equal(submissions, 0);
await returned.close();
console.log("Verified desktop and mobile, source disclosure, intel to person to intel, explicit identity selection, recoverable errors, Escape, newly indexed result continuation, and no overflow.");
